irq_id[4:3] (the highest id is N-1=7); unused_wdata (it is &{1'b0, wdata}, so always 0). Toggle points on these signals should be listed as unreachable, not covered. The loop variable i is an integer, and the knowledge document says Verilator does not toggle-count integers. Edges at time zero may be counted. The testbench cannot zero coverage before reset is released, because pragmas and $c are refused in non-design files. Measured percentages and any remaining uncovered points are pending the platform's coverage.read run, and the line/toggle bounds are not stated in my inputs."}], "files": [{"path": "irq_ctrl_cov_tb.sv", "kind": "testbench", "title": "irq_ctrl_cov_tb: self-checking coverage testbench for irq_ctrl (N=8)", "summary": "Extends [artifact:prj-63d6b8e26c.testbench.a1] to exercise every path of [artifact:prj-63d6b8e26c.design-under-test.a1]: level and edge detection, mixed modes, W1C, acknowledge (in range and out of range), detection beating a clear on the same edge, fixed priority, enable gating, and reset from a non-zero state. It checks every result. It prints the NIRMAAN-SIM verdict line with the plusarg nonce, as the approved testbench does. It uses no include, pragma, $fopen, $system, $c or DPI. Serves [requirement:req-1e26d9c190].", "entry": "irq_ctrl_cov_tb"}], "tool_runs": [], "claims": ["I have not run the testbench. Whether it passes on the approved RTL, and what line and toggle coverage it reaches, is unknown until the platform runs coverage.read.", "rdata[30:8], irq_id[4:3] and unused_wdata are expected to be unreachable for N=8, based on reading the RTL source. No tool has confirmed this.", "The expected values in the testbench come from my reading of irq_ctrl.v. If any of them is wrong, the run will report a failed check."], "escalation": null, "notes": "Top module for coverage.read is irq_ctrl_cov_tb. The design file is irq_ctrl.v. The testbench uses timing controls (#, @) in the same style as the approved idle testbench, so the platform's Verilator build has to support timing as it does for that file. The sections I was given do not state numeric coverage bounds. If the bounds count the justified-unreachable toggle points (rdata[30:8], irq_id[4:3], unused_wdata), toggle coverage cannot reach 100 percent for N=8, and the bound owner must accept those exclusions. The independent review evidence must be recorded by a different seat after the platform's run."}

=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v (N = 8). Extends irq_ctrl_idle_tb.sv:
// besides reset values and register read-back, it raises every source in level
// and edge mode, checks pending, irq, irq_id and CLAIM, clears by W1C and by
// acknowledge, checks that a detection wins over a clear at the same edge, that
// out-of-range acknowledges do nothing, that disabled sources do not interrupt,
// and that reset clears a non-zero state. Every check is self-checking; the
// verdict line is the same NIRMAAN-SIM line as the approved testbench.
//
// Expected unreachable points for N = 8 (see coverage report): rdata[30:8],
// irq_id[4:3], unused_wdata.
`timescale 1ns / 1ps
module irq_ctrl_cov_tb;
    localparam int N = 8;
    localparam logic [1:0] A_ENABLE = 2'd0, A_MODE = 2'd1, A_PENDING = 2'd2, A_CLAIM = 2'd3;

    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic [7:0]  src = 8'd0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    logic [4:0]  irq_id;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    irq_ctrl #(.N(N)) dut (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
                           .rdata(rdata), .irq(irq), .irq_id(irq_id));

    always #5 clk = ~clk;

    task automatic check(input logic ok, input string what);
        checks++;
        if (ok !== 1'b1) begin
            errors++;
            $display("FAIL at %0t: %0s", $time, what);
        end
    endtask

    task automatic tick();
        @(posedge clk);
        #1;
    endtask

    task automatic wr(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1;
        addr = a;
        wdata = d;
        tick();
        we = 1'b0;
        wdata = 32'd0;
    endtask

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected, input string what);
        addr = a;
        #1;
        check(rdata === expected, what);
    endtask

    task automatic expect_irq(input logic exp_irq, input logic [4:0] exp_id, input string what);
        #1;
        check((irq === exp_irq) && (irq_id === exp_id), what);
    endtask

    initial begin
        // ---- 1. Reset wins over a write and a high source ----
        @(posedge clk);
        #1;
        src = 8'hFF;
        we = 1'b1;
        addr = A_ENABLE;
        wdata = 32'hFFFF_FFFF;
        repeat (2) @(posedge clk);
        #1;
        src = 8'h00;
        we = 1'b0;
        wdata = 32'd0;
        rst_n = 1'b1;
        tick();
        expect_reg(A_ENABLE,  32'd0, "ENABLE is 0 after reset; write during reset ignored");
        expect_reg(A_MODE,    32'd0, "MODE is 0 after reset");
        expect_reg(A_PENDING, 32'd0, "PENDING is 0 after reset; source during reset ignored");
        expect_reg(A_CLAIM,   32'd0, "CLAIM reads 0 after reset");
        expect_irq(1'b0, 5'd0, "no irq after reset");

        // ---- 2. Register access, every wdata bit ----
        wr(A_ENABLE, 32'hFFFF_FFFF);
        expect_reg(A_ENABLE, 32'h0000_00FF, "ENABLE keeps bits below N and ignores the rest");
        wr(A_MODE, 32'hFFFF_FFFF);
        expect_reg(A_MODE, 32'h0000_00FF, "MODE keeps bits below N and ignores the rest");
        expect_reg(A_PENDING, 32'd0, "no source, nothing pending");
        expect_irq(1'b0, 5'd0, "no source, no irq");
        wr(A_ENABLE, 32'h0000_00A5);
        expect_reg(A_ENABLE, 32'h0000_00A5, "ENABLE read-back A5");
        wr(A_MODE, 32'h0000_005A);
        expect_reg(A_MODE, 32'h0000_005A, "MODE read-back 5A");
        wr(A_PENDING, 32'hFFFF_FFFF);
        expect_reg(A_PENDING, 32'd0, "W1C on empty PENDING keeps it 0");
        wr(A_CLAIM, 32'hFFFF_FFFF);
        expect_reg(A_ENABLE, 32'h0000_00A5, "CLAIM write leaves ENABLE");
        expect_reg(A_MODE, 32'h0000_005A, "CLAIM write leaves MODE");
        wr(A_ENABLE, 32'd0);
        wr(A_MODE, 32'd0);
        expect_reg(A_ENABLE, 32'd0, "ENABLE cleared");
        expect_reg(A_MODE, 32'd0, "MODE cleared");

        // ---- 3. Level mode, each source alone, then acknowledged ----
        wr(A_ENABLE, 32'h0000_00FF);
        for (int k = 0; k < N; k++) begin
            src = 8'h01 << k;
            tick();
            expect_reg(A_PENDING, 32'h1 << k, "level source sets its own pending bit");
            expect_irq(1'b1, k[4:0], "irq_id names the single active source");
            expect_reg(A_CLAIM, {1'b1, 26'd0, k[4:0]}, "CLAIM reads irq and id");
            src = 8'h00;
            wr(A_CLAIM, {27'd0, k[4:0]});
            expect_reg(A_PENDING, 32'd0, "acknowledge clears the named source");
            expect_irq(1'b0, 5'd0, "no irq after acknowledge");
        end

        // ---- 4. Priority, detection beats clear, W1C, out-of-range acknowledge ----
        src = 8'hFF;
        tick();
        expect_reg(A_PENDING, 32'h0000_00FF, "all level sources pending");
        expect_irq(1'b1, 5'd0, "lowest-numbered active source wins");
        wr(A_PENDING, 32'h0000_00FF);
        expect_reg(A_PENDING, 32'h0000_00FF, "detection wins over W1C at the same edge");
        wr(A_CLAIM, 32'd0);
        expect_reg(A_PENDING, 32'h0000_00FF, "detection wins over acknowledge at the same edge");
        src = 8'h00;
        wr(A_PENDING, 32'h0000_000F);
        expect_reg(A_PENDING, 32'h0000_00F0, "W1C clears only the bits written as 1");
        expect_irq(1'b1, 5'd4, "next priority is source 4");
        wr(A_CLAIM, 32'h0000_001F);
        expect_reg(A_PENDING, 32'h0000_00F0, "acknowledge id 31 (>= N) clears nothing");
        wr(A_CLAIM, 32'h0000_0008);
        expect_reg(A_PENDING, 32'h0000_00F0, "acknowledge id 8 (= N) clears nothing");
        wr(A_CLAIM, 32'hFFFF_FFE4);
        expect_reg(A_PENDING, 32'h0000_00E0, "acknowledge uses wdata[4:0] only (id 4)");
        expect_irq(1'b1, 5'd5, "next priority is source 5");
        wr(A_CLAIM, 32'h0000_0005);
        expect_reg(A_PENDING, 32'h0000_00C0, "acknowledge 5");
        expect_irq(1'b1, 5'd6, "next priority is source 6");
        wr(A_CLAIM, 32'h0000_0006);
        expect_reg(A_PENDING, 32'h0000_0080, "acknowledge 6");
        expect_irq(1'b1, 5'd7, "next priority is source 7");
        expect_reg(A_CLAIM, {1'b1, 26'd0, 5'd7}, "CLAIM reads irq with id 7");
        wr(A_CLAIM, 32'h0000_0007);
        expect_reg(A_PENDING, 32'd0, "acknowledge 7 empties PENDING");
        expect_reg(A_CLAIM, 32'd0, "CLAIM reads 0 when nothing active");
        expect_irq(1'b0, 5'd0, "no irq when nothing pending");

        // ---- 5. Enable gating ----
        src = 8'h81;
        tick();
        src = 8'h00;
        expect_reg(A_PENDING, 32'h0000_0081, "sources 0 and 7 pending");
        expect_irq(1'b1, 5'd0, "source 0 wins");
        wr(A_ENABLE, 32'h0000_0080);
        expect_irq(1'b1, 5'd7, "disabled source 0 skipped, source 7 claimed");
        wr(A_ENABLE, 32'd0);
        expect_irq(1'b0, 5'd0, "pending but disabled: no irq");
        expect_reg(A_CLAIM, 32'd0, "CLAIM reads 0 when all disabled");
        expect_reg(A_PENDING, 32'h0000_0081, "disabling keeps pending bits");
        wr(A_ENABLE, 32'h0000_00FF);
        expect_irq(1'b1, 5'd0, "re-enabling restores irq");
        wr(A_PENDING, 32'h0000_0081);
        expect_reg(A_PENDING, 32'd0, "W1C clears both");
        expect_irq(1'b0, 5'd0, "no irq after W1C");

        // ---- 6. Edge mode ----
        wr(A_MODE, 32'h0000_00FF);
        src = 8'h3C;
        tick();
        expect_reg(A_PENDING, 32'h0000_003C, "rising edges set pending");
        expect_irq(1'b1, 5'd2, "lowest rising source is 2");
        tick();
        expect_reg(A_PENDING, 32'h0000_003C, "held high: pending held, no new detection");
        wr(A_PENDING, 32'h0000_003C);
        expect_reg(A_PENDING, 32'd0, "edge mode: clear sticks while source held high");
        expect_irq(1'b0, 5'd0, "no irq after clear in edge mode");
        src = 8'h00;
        tick();
        expect_reg(A_PENDING, 32'd0, "falling edge is not detected");
        src = 8'h02;
        tick();
        expect_reg(A_PENDING, 32'h0000_0002, "rising edge on source 1");
        expect_irq(1'b1, 5'd1, "source 1 claimed");
        wr(A_CLAIM, 32'h0000_0001);
        expect_reg(A_PENDING, 32'd0, "edge mode: acknowledge sticks while source held");
        src = 8'h00;
        tick();
        src = 8'hC3;
        tick();
        expect_reg(A_PENDING, 32'h0000_00C3, "rising edges on 0, 1, 6, 7");

        // ---- 7. Mixed mode: sources 0-3 edge, 4-7 level ----
        wr(A_MODE, 32'h0000_000F);
        expect_reg(A_MODE, 32'h0000_000F, "MODE mixed");
        expect_reg(A_PENDING, 32'h0000_00C3, "mode change alone does not detect");
        wr(A_PENDING, 32'h0000_00FF);
        expect_reg(A_PENDING, 32'h0000_00C0, "level sources re-detect, edge sources clear");
        expect_irq(1'b1, 5'd6, "source 6 claimed");
        src = 8'h00;
        wr(A_PENDING, 32'h0000_00FF);
        expect_reg(A_PENDING, 32'd0, "all cleared once sources are low");

        // ---- 8. Reset from a non-zero state ----
        src = 8'hFF;
        tick();
        expect_reg(A_PENDING, 32'h0000_00FF, "all pending before reset");
        rst_n = 1'b0;
        tick();
        expect_reg(A_ENABLE,  32'd0, "reset clears ENABLE");
        expect_reg(A_MODE,    32'd0, "reset clears MODE");
        expect_reg(A_PENDING, 32'd0, "reset clears PENDING");
        expect_irq(1'b0, 5'd0, "no irq in reset");
        src = 8'h00;
        rst_n = 1'b1;
        tick();
        expect_reg(A_PENDING, 32'd0, "PENDING stays 0 after reset release");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
